select bb.bookset_id as booksetId, bb.subject_no as subjectNo, bb.balance_date as balanceDate, bb.bal_flag as balFlag, IFNULL(bb.o_amt, 0) as oAmt, IFNULL(bb.o_d_amt, 0) as oDAmt, IFNULL(bb.o_c_amt, 0) as oCAmt, IFNULL(O_CO_AMT,0) as oCoAmt, IFNULL(O_CO_C_AMT,0) as oCoCAmt, IFNULL(O_CO_D_AMT,0) as oCoDAmt, IFNULL(TDY_O_C_AMT,0) as tdyOCAmt, IFNULL(TDY_O_D_AMT,0) as tdyODAmt, IFNULL(TDY_O_CO_C_AMT,0) as tdyOCoDAmt, IFNULL(TDY_O_CO_D_AMT,0) as tdyOCoCAmt from BOK_BALANCE bb INNER JOIN REP_PROD_INFO RP ON BB.BOOKSET_ID=RP.F_PROD_ID where RP.PROD_ID= #{booksetId}
AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') = #{vdate1,jdbcType=VARCHAR}
and bb.subject_no like '4%' AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') > #{vdate1,jdbcType=VARCHAR} AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') <= #{mdate,jdbcType=VARCHAR}

