select bb.bookset_id as booksetId, bb.subject_no as subjectNo, bb.balance_date as balanceDate, bb.bal_flag as balFlag, IFNULL(bb.b_amt, 0) as bAmt, IFNULL(bb.b_d_amt, 0) as bDAmt, IFNULL(bb.b_c_amt, 0) as bCAmt, IFNULL(B_CO_AMT,0) as bCoAmt, IFNULL(B_CO_C_AMT,0) as bCoCAmt, IFNULL(B_CO_D_AMT,0) as bCoDAmt, IFNULL(TDY_B_C_AMT,0) as tdyBCAmt, IFNULL(TDY_B_D_AMT,0) as tdyBDAmt, IFNULL(TDY_B_CO_C_AMT,0) as tdyBCoCAmt, IFNULL(TDY_B_CO_D_AMT,0) as tdyBCoDAmt, IFNULL(TDY_PUR_B_D_ULAMT,0) as tdyPurBDUlamt, IFNULL(TDY_RED_B_D_ULAMT,0) as tdyRedBDUlamt, IFNULL(TDY_PUR_B_C_ULAMT,0) as tdyPurBCUlamt, IFNULL(TDY_RED_B_C_ULAMT,0) as tdyRedBCUlamt
from BOK_BALANCE bb INNER JOIN REP_PROD_INFO RP ON BB.BOOKSET_ID=RP.F_PROD_ID where RP.PROD_ID= #{booksetId}
and (bb.subject_no like '2%' or bb.subject_no in ('4002','4003','4011','4103','4104') or bb.subject_no like '6%') and bb.SUBJECT_LEVEL='1' AND DATE_FORMAT(bb.balance_date,'%Y-%m-%d') = #{vdate1,jdbcType=VARCHAR} union all
